"""Normalize the inherited bank and build original, syllabus-aligned practice items.
No generated item is represented as a past-paper question or medically peer reviewed.
"""
import json
import hashlib
import random
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
legacy = json.loads((ROOT / 'data/legacy-questions.json').read_text(encoding='utf-8-sig'))
bank, seen = [], set()
for item in legacy:
    text = item['q'].replace('[রিভিশন] ', '').strip()
    if text in seen:
        continue
    seen.add(text)
    i = len(bank)
    topic = 'সাহিত্য' if i < 39 else 'ব্যাকরণ' if i < 66 else 'বাগধারা ও শব্দভান্ডার'
    bank.append(dict(item, q=text, id=f'bn-{i+1:03}', subject='bangla', topic=topic,
                     type='practice', difficulty='easy', editorial='inherited-unreviewed', source=''))

